  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Allow overriding the static list via a JSON file (useful for tests or dev)
// Example: USER_SEED_FILE=./seed/users.json
if (process.env.USER_SEED_FILE) {
