    const filePath = path.resolve(process.env.USER_SEED_FILE);
    const raw = fs.readFileSync(filePath, 'utf8');
    USERS = JSON.parse(raw);
    console.info(`Loaded ${USERS.length} users from ${filePath}`);
  } catch (e) {
    console.warn('Failed to load USER_SEED_FILE, falling back to built‑in stub:', e);
  }
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    version: VERSION,
    timestamp: new Date().toISOString(),
  });
});

app.get('/users', (req, res) => {
  // In production you would protect this route with authentication/authorization.
  // For now we only return non‑sensitive fields; remove email if you want stricter privacy.
  const safeUsers = USERS.map(u => ({ id: u.id, name: u.name })); // drop email
  res.json(safeUsers);
});

// ---------- Global Error Handler ----------
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------- Server start ----------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

