```js
// app.js
require('dotenv').config();               // <-- loads .env files (optional)
const express = require('express');
const helmet = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

/* -----------------------  Configuration ----------------------- */
const PORT = parseInt(process.env.PORT, 10) || 3000;

// Example of externalised data (could be a DB query in production)
const USER_DATA_PATH = process.env.USER_DATA_PATH || './data/users.json';
let users = [];
try {
  users = require(USER_DATA_PATH);        // simple JSON file import
} catch (_) {
  // fallback to the hard‑coded example if the file is missing
  users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ];
}

/* -----------------------  Middleware ----------------------- */
app.use(helmet());
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100
}));
app.use(express.json());

/* -----------------------  Routes ----------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real deployment you would protect this endpoint or mask PII
  res.json(users);
});

/* -----------------------  Error handling ----------------------- */
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

/* -----------------------  Server start ----------------------- */
const server = app.listen(PORT, process.env.HOST || '127.0.0.1', () => {
  console.log(`Server running on http://${process.env.HOST || '127.0.0.1'}:${PORT}`);
});

/* Graceful shutdown (optional but recommended) */
function shutdown() {
  server.close(() => {
    console.log('Server stopped');
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

module.exports = app;
```

**What this change gives you**

1. **Port flexibility** – `PORT` can be supplied by the deployment environment (Docker `-p`, Kubernetes `containerPort`, Heroku dyno, etc.) without code modification.  
2. **Externalized user data** – By reading a JSON file (or later a DB) you avoid embedding personal data in code. The path itself can be set via `USER_DATA_PATH`.  
3. **Configurable security knobs** – CORS origin, rate‑limit max, host binding, etc., are now driven by env vars, making the same binary usable across dev, test, and prod.  
4. **Future‑proofing** – Any additional secrets (DB credentials, third‑party API keys) should follow the same pattern (`process.env.VAR_NAME`).  

